  .detail th, .detail td, .history th, .history td { padding: 7px 3px; font-size: .77rem; overflow-wrap: anywhere; }
  .catalog th, .catalog td { padding: 4px; font-size: .72rem; overflow-wrap: anywhere; }
  .catalog .pick { font-size: .76rem; min-width: 0; padding-inline: 3px; }
  .drawer { padding-inline: 8px; }
}
